import{z as i,x as s,o as r,c as m,q as l,j as t,D as e,d as o,s as n,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"道德风险的深化","description":"","frontmatter":{"title":"道德风险的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ct-moral-hazard-deep.md","filePath":"econ/ct-moral-hazard-deep.md","lastUpdated":1791063341000}'),d={name:"econ/ct-moral-hazard-deep.md"};function p(C,a,c,h,D,f){const B=s("Mermaid");return r(),m("div",null,[a[2]||(a[2]=l('<h1 id="道德风险的深化" tabindex="-1">道德风险的深化 <a class="header-anchor" href="#道德风险的深化" aria-label="Permalink to &quot;道德风险的深化&quot;">​</a></h1><div class="epigraph"><p>若代理人是风险中性且无财富约束，把剩余全部卖给他就是唯一需要的合同；本课从追问这个解为什么买不到开始。</p><footer>—— 据 Holmström, Bell Journal of Economics, 1979；Grossman and Hart, Econometrica, 1983 整理</footer></div><p><a href="/econ/bm-map">上一课</a>把银行与中介的深化收束：挤兑是可跑的债，资本是监督的押金，影子银行是工序的外移——全是合同问题的银行特例。本课程从银行转向一般的合同与机制设计，第一站回到隐藏行动：<a href="/econ/moral-hazard">道德风险</a>给了风险—激励权衡的直觉，<a href="/econ/principal-agent">委托–代理</a>把 IC–IR 写成规划，<a href="/econ/holmstrom-informativeness">充足统计</a>与<a href="/econ/limited-liability-mh">有限责任</a>各切了一刀。本课把刀口对齐：一阶方法何时合法、工资形状由什么钉住、实践里的线性合同为什么反而赢。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基础课留下三个缺口。其一，连续行动下把激励相容约束换成一阶条件，解出来的是「似然比写进工资」，但一阶条件只保证局部最优，全局 IC 不一定跟着满足，按它算出的合同可能实施不了目标努力。其二，充足统计与相对绩效说了哪些信号该进合同，没说工资该是什么形状——为什么保险用免赔额加共保、高管期权偏凸、中间层的奖金几乎线性。其三，没有有限责任时第一最佳能被极端罚金逼近，现实合同从不这么写；约束卡在哪一层，决定后面全部设计空间。</p><p><span class="marginnote">术语翻译：一阶方法就是「把代理人愿意选这个努力」翻译成一条导数等于零的方程来解合同。它便宜好用，但导数为零只说明是个平点——可能是山顶，也可能是鞍点。Rogerson 的两个条件正是担保书：有了它们，每个局部平点才都是全局峰顶。</span></p><h3 id="一阶方法的合法条件" tabindex="-1">一阶方法的合法条件 <a class="header-anchor" href="#一阶方法的合法条件" aria-label="Permalink to &quot;一阶方法的合法条件&quot;">​</a></h3><p>把 IC 换成一阶条件，要单调似然比与凸的分布函数条件护航：前者保证奖励高结果等价于奖励高努力，后者保证代理人目标在行动上凹，局部最优即全局。两组条件由 Rogerson 在 1985 年补齐，此前按一阶方法算出的合同可能根本无人按设定执行。条件不齐时解退回角点：<a href="/econ/limited-liability-mh">有限责任课</a>已见过，单调性下最优工资变成债式结构。</p><p><span class="marginnote">有限责任一撤，把最坏结果上的支付推向负无穷，代理人被恐惧钉在第一最佳努力上，信息成本趋近于零；真实约束不在效用函数里，而在财富与法庭上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>条件不齐时的正规做法是 Grossman–Hart 1983 的两步实施。先固定目标行动，求「诱出这个行动所需的最廉价合同」——给定行动的成本最小化，不需要一阶条件；再把每个行动的成本与期望产出放在一起比，选净值最大的行动。这个翻转把「写合同」变成「给每个行动标价」，一阶方法失效与否只是标价曲线光滑与否的副产品。</p>',11)),(r(),t(A,null,{default:e(()=>[n(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%AE%BE%E8%AE%A1%E5%B7%A5%E8%B5%84%E5%90%88%E5%90%8C%20w(x)%22%5D%20--%3E%20CHECK%7B%22%E4%B8%80%E9%98%B6%E6%96%B9%E6%B3%95%E5%90%88%E6%B3%95%EF%BC%9F%22%7D%0A%20%20CHECK%20--%3E%7C%22MLRP%20%E4%B8%8E%20CDFC%20%E6%88%90%E7%AB%8B%22%7C%20FOC%5B%22%E5%86%85%E7%82%B9%E8%A7%A3%EF%BC%9A%E4%BC%BC%E7%84%B6%E6%AF%94%E5%86%99%E8%BF%9B%E5%B7%A5%E8%B5%84%22%5D%0A%20%20CHECK%20--%3E%7C%22%E8%A7%92%E7%82%B9%E6%88%96%E9%9D%9E%E5%87%B9%22%7C%20GH%5B%22%E4%B8%A4%E6%AD%A5%E5%AE%9E%E6%96%BD%EF%BC%9A%E5%85%88%E9%92%89%E8%A1%8C%E5%8A%A8%E5%86%8D%E4%B9%B0%E5%90%88%E5%90%8C%22%5D%0A%20%20FOC%20--%3E%20LIN%5B%22%E8%BF%9E%E7%BB%AD%E8%A1%8C%E5%8A%A8%20%2B%20CARA%20%2B%20%E6%AD%A3%E6%80%81%EF%BC%9A%E7%BA%BF%E6%80%A7%E5%B7%A5%E8%B5%84%22%5D%0A%20%20GH%20--%3E%20LIN%0A%20%20LIN%20--%3E%20AC%5B%22%E4%BB%A3%E7%90%86%E6%88%90%E6%9C%AC%20%3D%20%E5%89%A9%E4%BD%99%E6%8D%9F%E5%A4%B1%20%2B%20%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"工资形状由三件事瓜分：风险分担要平滑，有限责任要下界，激励要对准似然比陡峭的区间。Holmström 与 Milgrom 在 1987 年给出一组互相咬合的假设——行动连续、代理人 CARA、噪声正态、合同只看加总绩效——最优解是线性工资 \\(\\alpha+\\beta x\\)：斜率 \\(\\beta\\) 随努力的边际产出上升，随风险的方差与行动成本曲率下降。线性的真正优势是聚合：多任务叠加、长任务流上，线性合同对分布的具体形状不敏感。现实合同几乎不写非线性：谈判双方无力核实那个足以支撑曲线的 \\(F(x\\mid a)\\)。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"Jensen 与 Meckling 在 1976 年把同一套逻辑做成账目：代理成本 = 监督支出 + 担保支出 + 剩余损失。道德风险从定理变成资产负债表上的科目，才有公司金融里用融资结构购买激励的整套分析。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：工资 \\(\\alpha+\\beta x\\) 里，斜率 \\(\\beta\\) 就是「多挣一元归自己」的比例。若 \\(\\beta=0.5\\)、产出 \\(x=100\\)，绩效工资是 50；若产出方差很大（比如风险高的销售岗），风险厌恶的代理人会要求要么调低 \\(\\beta\\)、要么提高固定部分 \\(\\alpha\\) 来补偿——「提成高底薪低」只适合波动小的业务，直觉与公式在这里重合。")],-1)),(r(),t(A,null,{default:e(()=>[n(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20B%5B%22%E6%BF%80%E5%8A%B1%E6%96%9C%E7%8E%87%20%CE%B2%20%E5%AE%9A%E5%A4%9A%E5%BC%BA%22%5D%20--%3E%20UP%5B%22%E8%BE%B9%E9%99%85%E4%BA%A7%E5%87%BA%E9%AB%98%20%E2%86%92%20%CE%B2%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20B%20--%3E%20DN1%5B%22%E4%BA%A7%E5%87%BA%E6%96%B9%E5%B7%AE%E5%A4%A7%20%E2%86%92%20%CE%B2%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20B%20--%3E%20DN2%5B%22%E8%A1%8C%E5%8A%A8%E6%88%90%E6%9C%AC%E6%9B%B2%E7%8E%87%E5%A4%A7%20%E2%86%92%20%CE%B2%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LL%5B%22%E6%9C%89%E9%99%90%E8%B4%A3%E4%BB%BB%20%E2%86%92%20%E5%B7%A5%E8%B5%84%E6%9C%89%E4%B8%8B%E7%95%8C%22%5D%20--%3E%20W%5B%22%E5%B7%A5%E8%B5%84%20%3D%20%CE%B1%20%2B%20%CE%B2x%22%5D%0A%20%20UP%20--%3E%20W%0A%20%20DN1%20--%3E%20W%0A%20%20DN2%20--%3E%20W%0A%20%20S%5B%22%E4%BC%BC%E7%84%B6%E6%AF%94%E9%99%A1%E5%B3%AD%E5%8C%BA%E9%97%B4%20%E2%86%92%20%CE%B2%20%E5%AF%B9%E5%87%86%E9%82%A3%E9%87%8C%22%5D%20--%3E%20W%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>道德风险也接回公司边界：股东与经理、债权人与股东之间的合同本身就是激励工具，债务的还本付息是逼出现金、削掉乱花的承诺装置，与<a href="/econ/pecking-order">优序融资</a>的信息成本账并行；任务多维时<a href="/econ/multitask-holmstrom">可测性不对称</a>会改写一切，一维规划不可直接搬。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课仍是一次性、单代理人、行动一维。隐性激励属于<a href="/econ/career-concerns">职业关注</a>，市场推断可以替代显性合同；团队与合谋留给多边机制课。最大的缺口是时间：今天的产出明天还能用——合同会续写、条款会重谈，充足统计的静态权重不再最优——这是下一课动态合同的入口。</p><p><span class="marginnote">术语翻译：职业关注就是「没有奖金条款，但市场在给我的履历打分」。年轻医生多做研究不是为了当期提成，而是为了下一份聘书——市场用产出更新对他能力的估计，这份「明天的估值」替代了显性合同里的奖金。它前期最强（推断最灵敏），随履历定型而衰减。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一阶方法要 MLRP 与凸分布条件护航，否则解出的是不可实施的合同。</li><li>条件不齐用两步实施：先给每个行动标价，再挑净值最大的行动。</li><li>风险分担、有限责任、似然比共同定工资形状；CARA 加正态下线性最优且抗聚合。</li><li>有限责任撤掉的极限里第一最佳靠极端罚金逼近，现实卡在财富与法庭。</li><li>代理成本三件套把道德风险做成可测科目，接通公司金融。</li><li>出处：Holmström, <em>Bell</em> 1979；Grossman and Hart, <em>Econometrica</em> 1983；Rogerson, <em>JET</em> 1985；Holmström and Milgrom, <em>Econometrica</em> 1987；Jensen and Meckling, <em>JFE</em> 1976。</li></ul>',6))])}const _=i(d,[["render",p]]);export{b as __pageData,_ as default};
